                    if (kind == 10 && f.Kind == 11) { raw = WidenFloat((uint)raw); }
                    if (f.ClampRaw != null) { raw = f.ClampRaw(raw, report); }
                }
                if (f.GetBuffer != null) { value.Buffer(f)[index] = (byte)raw; }
                else { value.SetRaw(f,index,raw); }
